import {latinDigits} from './search.js';
const partsFormatter=new Intl.DateTimeFormat('en-US-u-ca-persian',{timeZone:'Asia/Tehran',year:'numeric',month:'numeric',day:'numeric'});
export function persianParts(value=new Date()){const p=Object.fromEntries(partsFormatter.formatToParts(new Date(value)).map(x=>[x.type,x.value]));return {year:+p.year,month:+p.month,day:+p.day}}
export function formatDate(value,time=false){const d=new Date(value);return Number.isNaN(+d)?'نامشخص':new Intl.DateTimeFormat('fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',dateStyle:'medium',...(time?{timeStyle:'short'}:{})}).format(d)}
export function jalaliToISO(value,time='12:00'){const m=latinDigits(value).trim().match(/^(\d{4})[/-](\d{1,2})[/-](\d{1,2})$/);if(!m||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))return null;const [y,mo,day]=m.slice(1).map(Number);if(y<1300||y>1500||mo<1||mo>12||day<1||day>31)return null;const start=Date.UTC(y+621,2,19,12);for(let i=0;i<368;i++){const d=new Date(start+i*86400000),p=persianParts(d);if(p.year===y&&p.month===mo&&p.day===day)return d.toISOString().slice(0,10)+'T'+time}return null}
export function dateInputValue(value=new Date()){const p=persianParts(value);return [p.year,p.month,p.day].map((x,i)=>i?String(x).padStart(2,'0'):x).join('/')}
export function initVisitDate(){const hidden=document.querySelector('#visitTime');hidden.type='hidden';const wrap=document.createElement('div');wrap.className='jalali-picker';wrap.innerHTML='<input id="visitDate" type="text" inputmode="numeric" placeholder="۱۴۰۵/۰۸/۰۱" aria-label="تاریخ مراجعه شمسی" dir="ltr"><input id="visitClock" type="time" value="12:00" aria-label="ساعت مراجعه به وقت تهران"><div><button type="button" data-visit-day="0">امروز</button><button type="button" data-visit-day="1">فردا</button><button type="button" data-visit-clear>پاک کردن</button></div><small>تاریخ شمسی · ساعت تهران</small>';hidden.after(wrap);const date=wrap.querySelector('#visitDate'),time=wrap.querySelector('#visitClock');function sync(){const iso=date.value?jalaliToISO(date.value,time.value):'';date.setCustomValidity(date.value&&!iso?'تاریخ شمسی معتبر وارد کنید؛ مانند ۱۴۰۵/۰۸/۰۱':'');hidden.value=iso||''}date.oninput=sync;time.oninput=sync;wrap.querySelectorAll('[data-visit-day]').forEach(b=>b.onclick=()=>{date.value=dateInputValue(Date.now()+Number(b.dataset.visitDay)*86400000);sync()});const reset=()=>{date.value='';date.setCustomValidity('');hidden.value=''};wrap.querySelector('[data-visit-clear]').onclick=reset;return {reset,valid:()=>{sync();return date.reportValidity()&&time.reportValidity()}}}
